    edges = [(a.get('i'), a.get('j'), a.get('distance_A') or 0.0) for a in s.get('neighbors') or []]
    bonds = [(i, j, ((1.35 - d / (radii[i] + radii[j])) / 0.35) ** 2) for i, j, d in edges if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d > 0 and radii[i] > 0 and radii[j] > 0 and d < 1.35 * (radii[i] + radii[j])]
    total = 0.0
    amount = 0.0
    for i, a in enumerate(sites):
        if radii[i] <= 0 or occ[i] <= 0:
            continue
        p = props.get(a.get('element')) or {}
        group = p.get('group')
        if p.get('Z') == 1:
            reference = 1.0
        elif group is not None and 13 <= group <= 17:
            reference = float(min(group - 10, 18 - group))
        else:
            continue
        coordination = sum(occ[j] * w for ii, j, w in bonds if ii == i)
        excess = max(0.0, coordination / reference - 1.0)
        value = float(np.log1p(excess))
        total += occ[i] * value * value
        amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0
